  'Manage language, theme, security, and notification settings from your account.' => 'Ji hesabê xwe mîhengên ziman, mijar, ewlehî û ragihandinê bi rê ve bibin.',
  'Max upload' => 'Max upload',
  'Media and analytics storage' => 'Hilberîna medya û analîtîk',
  'Messages submitted on the Contact page are saved and shown in the admin Support dashboard as contact tickets.' => 'Peyamên ku li ser rûpela Têkilî têne şandin di databasê de têne hilanîn û di tabloya Piştgiriya rêveberê de wekî bilêtên têkiliyê têne xuyang kirin.',
  'Moderation help' => 'Alîkariya Moderasyonê',
  'More⌄' => 'Zêdetir⌄',
  'Need help?' => 'Pêdivî bi alîkariyê heye?',
  'Need more help?' => 'Zêdetir alîkarî divê?',
  'No answers found for this topic and search.' => 'Ji bo vê mijarê û lêgerînê bersiv nehatin dîtin.',
  'No category activity found yet.' => 'Hê çalakiya kategoriyê nehatiye dîtin.',
  'No creator channels found yet.' => 'Tu kanalên afirîner hîn nehatine dîtin.',
  'No upload categories are configured.' => 'Tu kategoriyên barkirinê nehatine mîheng kirin.',
  'Non-refundable cases' => 'Dozên ku nayê vegerandin',
  'noopener,noreferrer' => 'noopener, noreferrer',
  'Normal priority' => 'Pêşîniya normal',
  'Not available' => 'Ne peyda dibe',
  'Not provided' => 'Ne pêşkêş kirin',
  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'Navnîşanên pêwendiya fermî, têkiliyên fatûreyê, û kanalên piştevaniya derve divê ji hêla rêvebirê malpera PlayHub ve ji bo vê bicîhkirinê werin mîheng kirin. Ev rûpel bi mebest navnîşanên e-nameya nerastkirî nîşan nade.',
  'On this page' => 'Li ser vê rûpelê',
  'Open Help Center' => 'Navenda Alîkariyê vekin',
  'Open settings' => 'Mîhengan vekin',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'Mîhengan vekin, biçin Ewlekariyê, dûv re şîfreya an diyaloga du-faktor bikar bînin. Radestkirina du-faktor dema ku were mîheng kirin e-name an têlefonê piştgirî dike.',
  'Operational snapshot' => 'Wêneya operasyonê',
  'Optional, but recommended' => 'Vebijarkî, lê tê pêşniyar kirin',
  'Other' => 'شتی تر',
  'Partnerships, press, and platform operations.' => 'Hevkarî, çapemenî û operasyonên platformê.',
  'Payment help' => 'Alîkariya dravdanê',
  'Platform' => 'Platform',
  'Playback' => 'Playback',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Pêşveçûna lîstikê, rewşa paşerojê, ecibandin, şîrove, abonetî, agahdarî, û analîzên rêveberiyê dema ku bi taybetmendiyên platformê yên pejirandî ve têne girêdan di databasê de têne hilanîn.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Playback, şîrove, ecibandin, paşê temaşe bikin, abonetî, agahdarî, peyam, lîsteyên lîstikê, û mîhengên zimanî bi navîgasyon û menuya hesabê sereke têne peyda kirin.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub platformek vîdyoyê ye ji bo barkirin, temaşekirin, plansazkirin, rêvebirin û moderatoriya naveroka afirînerê ji yek hesabê.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub platforma vîdyoyê ye ku li ser vê bicîhkirinê tê xebitandin, ji bo afirîner, temaşevan, civak û operatorên platformê hatî çêkirin.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub ji yek platformê kanalên afirîner, barkirinên vîdyoyê, weşana plansazkirî, abonetî, şîrove, navnîşên lîstikê, temaşekirina paşê, rûpelên naveroka zindî, û amûrên rêveberiyê peyda dike.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ji bo danişînên têketinê, erêkirina API-ê, tevgera CSRF/ewlehiyê, hilbijartina ziman, hilbijartina mijarê, rewşa menuya hesabê, û taybetmendiyên din ên ku ji bo xebitandina serîlêdanê hewce ne, çerezên bingehîn û hilanîna gerokê bikar tîne.',
  'playhub_language, theme' => 'playhub_language, tema',
  'Popular questions' => 'Pirsên populer',
  'Preference storage' => 'depo Preference',
  'Privacy Policy' => 'Privacy Policy',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'Nepenî, cookie, ewlehiya hesabê, peyamên piştgirî, û daneyên nermalav bi navgîniya polîtîka û tomarên paşîn ên ku bi PlayHub-ê ve girêdayî ne têne rêve kirin.',
  'Profile, login, security, and settings help.' => 'Profîl, têketin, ewlehî, û mîhengan alîkarî dikin.',
  'Profile, security, and preferences.' => 'Profîl, ewlehî, û tercîhên.',
  'Public API route' => 'Rêça API-ya gelemperî',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'Xalên dawiya JSON-ê yên gelemperî /api/tenduristî ji bo statûya bicîhkirinê û /api/upload-vebijarkên ji bo kategoriyên barkirinê, ziman, sînor, mezinahiya perçeyê, û etîketên trendê vedihewîne.',
  'Public REST API' => 'Giştî REST API',
  'Published videos' => 'Vîdyoyên weşandin',
  'Purchase date' => 'Dîroka kirînê',
  'purchaseDate' => 'buyDate',
  'Purpose' => 'Armanc',
  'Questions about privacy?' => 'Pirsên li ser nepenîtiyê?',
