  'Platform overview' => 'Daneyên platformê yên rastîn',
  'Reason' => 'Reason',
  'Recent creator channels' => 'Kanalên afirînerê dawî',
  'Refund' => 'Vegerandin',
  'Refund and paid feature guidance.' => 'Vegerandin û rêbernameya taybetmendiya dravê.',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'Vegerandina dravê ji bo taybetmendiyên PlayHub-ê yên dravî bi tomarên fatûreya rastîn ên ku bi vê bicîhkirinê ve girêdayî ne ve girêdayî ye.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'Vegerandina drav bi tomarên fatûreya rastîn û vekolîna rêveberê ve girêdayî ye. Ger fatûre ji bo vê bicîhkirinê nehatibe mîheng kirin, ji bo vegerandina dravê ti berdêlek platformê tune.',
  'Refund issued' => 'Vegerandin hat dayîn',
  'Refund page' => 'Rûpelê vegerandin',
  'Refund Policy' => 'Siyaseta Vegerandinê',
  'Refund reason' => 'Sedema vegerandinê',
  'Refund request' => 'Daxwaza vegerandinê',
  'Refund request process' => 'Pêvajoya daxwaza vegerandinê',
  'refund-dialog contact-message-form' => 'vegerandin-diyalog têkilî-peyam-forma',
