  'Report a problem' => 'Pirsgirêkek rapor bikin',
  'Reports, moderation, and privacy.' => 'Rapor, moderatorî, û nepenî.',
  'Reports, moderation, privacy, and community safety.' => 'Rapor, nermbûn, nepenî, û ewlehiya civakê.',
  'Request a refund' => 'Daxwaza vegerandin',
  'Required' => 'Required',
  'Required for login, security, and app routing.' => 'Ji bo têketin, ewlehî, û rêvekirina sepanê hewce ye.',
  'Response targets' => 'Armancên bersivê',
  'Retention and access' => 'Ragirtin û gihîştin',
  'Review privacy and cookie details for this deployment.' => 'Ji bo vê bicîhkirinê hûrguliyên nepenîtiyê û cookie-yê binirxînin.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'Rêbazên ji bo karanîna vê bicîhkirina PlayHub-ê wekî temaşeker, afirîner, an rêvebir.',
  'Safety' => 'Safety',
  'Safety / technical' => 'Ewlehî / teknîkî',
  'Safety and content reports' => 'Raporên ewlehî û naverokê',
  'Safety or report' => 'Ewlekarî an rapor',
  'Sample endpoints' => 'Nimûne xalên dawî',
  'sample endpoints loaded' => 'nuqteyên dawî yên nimûne barkirin',
  'Schedule video' => 'Vîdyoyê plansaz bikin',
  'Scheduled video release and reminders.' => 'Weşandina vîdyoyê û bîranînên plansazkirî.',
  'Scheduled videos' => 'Vîdyoyên plansazkirî',
  'Scheduling a video release' => 'Plansazkirina serbestberdana vîdyoyê',
  'Search for answers...' => 'Li bersivan bigerin...',
  'Search help articles, topics, or questions...' => 'Li gotar, mijar, an pirsan arîkariyê bigerin...',
  'Select a reason' => 'Sedemek hilbijêrin',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Yek an çend pelên vîdyoyê hilbijêrin, hûrguliyên hewce binivîsin, kategorî û ziman hilbijêrin, piçûkek lê zêde bikin, dîtinê hilbijêrin û biweşînin. Berî ku server dest bi pêvajoyê bike, pelên mezin bi perçeyan têne barkirin.',
  'Send a message and it will be saved for admins.' => 'Peyamek bişînin û ew ê ji bo rêvebiran were tomar kirin.',
  'Send billing details to admin support for review.' => 'Ji bo vekolînê hûrguliyên fatûreyê ji piştgiriya rêveber re bişînin.',
  'Send message' => 'Peyam bişînin',
  'Send order details through the refund popup.' => 'Hûrguliyên fermanê bi rêya popupa vegerandinê bişînin.',
  'Send us a message' => 'Ji me re peyamek bişînin',
  'Sending...' => 'Dişîne...',
  'Server configured' => 'Server mîheng kirin',
  'server records' => 'tomar server',
  'Service operation' => 'Operasyona xizmetê',
  'session, token' => 'danişîn, nîşan',
  'Settings and login' => 'Mîheng û têketinê',
  'Short summary' => 'Kurte kurt',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Têkeve û Mîhengan ji bo hesab, profîl, şîfre, agahdarî, nepenî, û vebijarkên afirînerê bikar bînin. Pirsgirêkên barkirina afirîner û naverokê divê sernavê vîdyoyê, kanal, gerok, û her xeletiyek pêvajoyê ya ku li ser rûpela barkirinê tê xuyang kirin hebe.',
  'Sign in for account support' => 'Ji bo piştgiriya hesabê têkevin',
  'Signed in' => 'Signed in',
  'Start uploading' => 'Dest bi barkirinê bikin',
  'Still can’t find an answer?' => 'Hîn jî nikarin bersivek bibînin?',
  'Stored for admins' => 'Ji bo rêveberan têne hilanîn',
  'Stores language, theme, and interface preferences.' => 'Ziman, mijar û vebijarkên navberê hildide.',
  'Studio, playlists, analytics, channels.' => 'Studio, lîsteyên lîstikê, analîtîk, kanal.',
  'Submit a billing or refund message to admin support.' => 'Ji piştevaniya rêveberê re peyamek billing an vegerandinê bişînin.',
  'Submit refund request' => 'Daxwaza vegerandinê bişînin',
  'Submit request' => 'Serlêdan bişînin',
  'Subscription cancellation' => 'Betalkirina abonetiyê',
  'Support dashboard' => 'dashboard piştgirî',
  'System status' => 'Rewşa pergalê',
  'Table' => 'Table',
  'Taxonomies' => 'Taxonomies',
  'Technical issue' => 'Pirsgirêka teknîkî',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Nîşaneyên teknîkî yên ji bo entegrasyonên bi PlayHub API-ya heyî û barkirina xebatê.',
  'Tell us more about your question or request...' => 'Di derbarê pirs an daxwaziya xwe de bêtir ji me re bêje...',
  'Terms of Use' => 'Mercên Bikaranînê',
  'The configured' => 'The mîheng kirin',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Rûpelê pêşdebir bi paşdeya zindî ya Laravel ve girêdayî ye: envantera rê, hejmartina databasê, sînorên barkirinê, û metadata platformê ji /api/pêşdebiran têne barkirin.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Pêşeng tercihên wekî zimanê bijartî, mijar, rêza lêdanê, pêşkeftina temaşekirinê, û rewşa navbeynkariyê hildide, ji ber vê yekê ezmûn li seranserê navîgasyon û barkirina rûpelan domdar bimîne.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Karê hilberandinê rengdêran şîfre dike, dema ku hewce bike nimûnan diafirîne, sernivîsan hilîne, û dema ku pêvajo bi dawî bibe vîdyoyên amade nîşan dide. Vîdyoyên plansazkirî yên pêşerojê nepenî dimînin heya ku plansaz wan berde.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Pergala barkirinê ji hêla databasê ve tê piştgirî kirin, kategorî û zimanên ji API-yê piştgirî dike, vîdyoyên hatine barkirin pêvajo dike, hûrguliyan û sernavan hilîne, û naveroka plansazkirî heya dema berdana wê nepenî digire.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Ev rûpel rave dike ka PlayHub çawa çerezan û hilanîna gerokê ji bo danişînan, ewlehî, vebijarkî, lîstin, û taybetmendiyên pejirandî bikar tîne.',
  'Ticket source' => 'Çavkaniya bilêtê',
  'Top content categories' => 'Kategoriyên naverokê yên jorîn',
  'Topic' => 'Mijar',
  'Transaction / invoice' => 'Danûstandin / fatûre',
  'Transaction / invoice ID' => 'Nasnameya danûstendinê / fatûre',
  'Unable to send message.' => 'Nikare peyam bişîne.',
  'Unable to submit refund request.' => 'Daxwaza vegerandinê nayê şandin.',
  'Understanding admin support tickets' => 'Fêmkirina bilêtên piştgiriya rêveberiyê',
  'Upload and processing help' => 'Alîkariya barkirin û pêvajoyê',
  'Upload chunks' => 'Parçeyan barkirin',
  'Upload issues' => 'Pirsgirêkên barkirin',
  'Upload languages' => 'Barkirina zimanan',
  'Upload limit' => 'Sînorê barkirin',
  'Upload options' => 'Vebijêrkên barkirin',
  'Upload or processing' => 'Barkirin an hilberandin',
  'Upload page' => 'Rûpelê barkirin',
  'Upload pipeline' => 'Barkirina boriyê',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Bi daneya zindî ya PlayHub re barkirin, temaşekirin, abone, nermkirin, û ava kirin.',
  'Uploaded videos' => 'Vîdyoyên barkirî',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Vîdyoyên barkirî di nav rêzikên ku têne lîstin de têne kod kirin. Dema pêvajoyê bi mezinahiya pelê, demdirêj, barkirina serverê, û rewşa dorê ve girêdayî ye. Rûpelê barkirinê û Afirînerê Studio statûya pêvajoyê ya rastîn ji tomara vîdyoyê nîşan dide.',
  'Uploads, scheduling, and processing are available.' => 'Barkirin, plansazkirin, û pêvajo hene.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Ji bo xebatên afirîner /api/vîdyoyan, xalên dawiya kanalê, û rêyên pejirandî bikar bînin.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Ji bo vîdyoyan û şîroveyan çalakiyên raporê yên çêkirî bikar bînin da ku rêvebir referansa naverokê ya rastîn bistînin. Rûpelên dashboarda rêveberê daneyên databasa zindî ji bo bikarhêneran, naverok, rapor, diravkirin, analîtîk, piştgirî, rol û mîhengên pergalê bikar tînin.',
  'Use Contact Us' => 'Bikar bînin Têkilî Bi me re',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'JSON ji bo daxwazên API-ya normal û FormData ji bo barkirina pelan bikar bînin. Qebûlkirinê derbas nekin: kategorî û ziman nasnameyên databasê ne, dîtin bi gelemperî, nelîstekirî, an taybet ve sînorkirî ye, û sernav pelên SRT, VTT, an TXT qebûl dikin.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Mîhengan bikar bînin da ku profîla xwe, ewlehî, şîfre, radestkirina du-faktor, cîhaz, vebijark û vebijarkên ragihandinê nûve bikin. Heke hûn nekarin bigihîjin hesabê xwe, herikîna têketinê bikar bînin û e-nameya hesabê ji rêveberê malperê re peyda bikin.',
  'Use the contact form' => 'Forma têkiliyê bikar bînin',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Çalakiyên raporê li ser vîdyoyan, şîrove û postên civakê bikar bînin da ku rêvebir referansa naverokê ya rastîn bistînin.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Gava ku naverok dibe ku qaîdeyên platformê binpê bike, kiryarên raporê li ser vîdyoyan, şîrove û postên civakê bikar bînin. Van raporên bi tomara naveroka rastîn ve girêdayî ne û ji peyamek gelemperî çêtir in ji ber ku rêvebir dikarin tiştê rastîn binirxînin.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Ji bo alîkariya hesabê, raporên naverokê, pirsgirêkên teknîkî, û daxwazên rêveberê kanala PlayHub-a rast bikar bînin.',
  'Video categories' => 'Kategoriyên vîdyoyê',
  'Video for everyone. Built for creators and viewers.' => 'Vîdyo ji bo her kesî. Ji daneyên platformê yên rastîn hatine çêkirin.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Pirsgirêkên barkirina vîdyoyê, plansazkirin, hûrgulî, û pêvajoyê.',
  'Videos, thumbnails, captions, processing.' => 'Vîdyo, hûrgulî, sernav, pêvajo.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Temaşevan dikarin li kategoriyan bigerin, li vîdyoyan bigerin, li naverokê temaşe bikin, bibin aboneyên kanalan, vîdyoyan hilînin da ku paşê temaşe bikin, şîrove bikin, agahdariyan bistînin, û vebijarkên ziman û gihîştinê birêve bibin.',
  'Viewing and community help' => 'Dîtin û alîkariya civakê',
  'Waiting for backend endpoint inventory.' => 'Li benda envantera xala dawiya paşerojê ye.',
  'We’re here to help.' => 'Em ji bo alîkariyê li vir in.',
  'What is PlayHub?' => 'PlayHub çi ye?',
  'What PlayHub does' => 'PlayHub çi dike',
  'Where do contact messages go?' => 'Peyamên têkiliyê li ku derê diçin?',
  'Why is my video still processing?' => 'Çima vîdyoya min hîn jî tê pêvajoyê?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Erê. Li ser rûpela barkirinê qada tarîx û demjimêra xwemalî bikar bînin. Piştgir scheduled_at hildide, vîdyoyê pêvajo dike, dema ku tarîx di pêşerojê de ye, wê nepenî digire, û dema ku plansazker Laravel piştî dema diyarkirî dimeşîne, wê diweşîne.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Erê. Zeviya bernameya xwemalî li ser Upload bikar bînin. The paşperdeya scheduled_at hildide û piştî pêvajoyê dema ku dema bernameyê bigihîje vîdyoyê belav dike.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Hûn wek mêvan lê geriyan. Têkeve ji bo gihîştina amûrên taybetî-hesab.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Hûn ji pêbaweriyên hesabê xwe, çalakiya profîlê, naveroka barkirî, şîrove, peyam, û her kiryarên afirîner an rêveberê ku ji hesabê we hatine kirin berpirsiyar in. Şîfreyên bihêz bikar bînin û rêbazên radestkirina du-faktorê heyî bihêlin.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Hûn dikarin di mîhengên geroka xwe de çerezên gerok û hilanîna herêmî paqij bikin. Paqijkirina hilanînê ya bingehîn dibe ku we ji we derxe, vebijarkên ziman/mijarê vegerîne, rewşa lîstika herêmî jê bibe û ji we hewce bike ku hûn dîsa têkevinê.',
  'You receive a response by email.' => 'Hûn bi e-nameyê bersivek distînin.',
